insert into public.recipe_categories (store_id, slug, name, description, position) values ((select id from public.stores where slug = 'cocteles'), 'clasicos-faciles', 'Clásicos fáciles', 'Los que todo el mundo reconoce y nunca fallan. Perfectos para empezar si nunca has preparado un cóctel: pocos ingredientes, técnica mínima y el sabor que la gente ya conoce.', 0) on conflict (store_id, slug) do update set name = excluded.name, description = excluded.description, position = excluded.position;
insert into public.recipe_categories (store_id, slug, name, description, position) values ((select id from public.stores where slug = 'cocteles'), 'con-aguardiente-y-sabores-colombianos', 'Con aguardiente y sabores colombianos', 'El aguardiente es el licor más fácil de conseguir en cualquier tienda del país, y combina muy bien con las frutas de clima tropical. Esta sección es la que más identifica a un recetario colombiano.', 1) on conflict (store_id, slug) do update set name = excluded.name, description = excluded.description, position = excluded.position;
insert into public.recipe_categories (store_id, slug, name, description, position) values ((select id from public.stores where slug = 'cocteles'), 'en-jarra-para-fiestas', 'En jarra para fiestas', 'Para cuando no quieres estar preparando vaso por vaso toda la noche. Se hacen de una sola vez en una jarra grande y cada quien se sirve.', 2) on conflict (store_id, slug) do update set name = excluded.name, description = excluded.description, position = excluded.position;
insert into public.recipe_categories (store_id, slug, name, description, position) values ((select id from public.stores where slug = 'cocteles'), 'con-vino', 'Con vino', 'Más elegantes, rinden mucho porque se sirven en jarra, y combinan bien con mesas de queso o postres.', 3) on conflict (store_id, slug) do update set name = excluded.name, description = excluded.description, position = excluded.position;
insert into public.recipe_categories (store_id, slug, name, description, position) values ((select id from public.stores where slug = 'cocteles'), 'nuevos-y-llamativos', 'Nuevos y llamativos', 'Ocho cócteles adicionales, elegidos por lo bien que se ven en fotos y porque usan ingredientes fáciles de encontrar en Colombia.', 4) on conflict (store_id, slug) do update set name = excluded.name, description = excluded.description, position = excluded.position;
insert into public.recipes (store_id, category_id, slug, title, position, photo_path, photo_people_path, yield_text, yield_servings, time_text, ingredients, steps, notes, extras) values ((select id from public.stores where slug = 'cocteles'), (select id from public.recipe_categories where store_id = (select id from public.stores where slug = 'cocteles') and slug = 'clasicos-faciles'), 'cuba-libre', 'Cuba libre', 0, 'cocteles/foto-cuba-libre.jpg', 'cocteles/gente-cuba-libre.jpg', '1 vaso alto (300 ml)', 1, '3 minutos', '[{"raw":"45 ml de ron blanco o añejo","qty":45,"rest":"ml de ron blanco o añejo"},{"raw":"120 ml de cola bien fría","qty":120,"rest":"ml de cola bien fría"},{"raw":"1/2 limón","qty":0.5,"rest":"limón"},{"raw":"Hielo al gusto","qty":null,"rest":"Hielo al gusto"}]'::jsonb, '["Llena el vaso con hielo hasta arriba.","Agrega el ron.","Completa con la cola.","Exprime el medio limón directo sobre el vaso y revuelve una vez con una cuchara larga."]'::jsonb, '[]'::jsonb, '{"adelanta":"Nada se adelanta: es de los que se armas al momento. Lo único que ayuda tener listo es el hielo en cubos grandes (se derrite más despacio) y el limón cortado en cuartos.","presentacion":"Vaso alto (highball), con una rodaja de limón en el borde.","conservacion":"Se toma de inmediato; no se guarda armado porque la cola pierde burbujas.","variacion":"Cambia el ron por más cola y un chorrito de jugo de limón: queda una limonada de cola.","variacion_titulo":"Sin alcohol"}'::jsonb) on conflict (store_id, slug) do update set category_id = excluded.category_id, title = excluded.title, position = excluded.position, photo_path = excluded.photo_path, photo_people_path = excluded.photo_people_path, yield_text = excluded.yield_text, yield_servings = excluded.yield_servings, time_text = excluded.time_text, ingredients = excluded.ingredients, steps = excluded.steps, notes = excluded.notes, extras = excluded.extras;
insert into public.recipes (store_id, category_id, slug, title, position, photo_path, photo_people_path, yield_text, yield_servings, time_text, ingredients, steps, notes, extras) values ((select id from public.stores where slug = 'cocteles'), (select id from public.recipe_categories where store_id = (select id from public.stores where slug = 'cocteles') and slug = 'clasicos-faciles'), 'mojito-cubano', 'Mojito cubano', 1, null, null, '1 vaso alto (300 ml)', 1, '8 minutos', '[{"raw":"45 ml de ron blanco","qty":45,"rest":"ml de ron blanco"},{"raw":"8 a 10 hojas de menta o hierbabuena","qty":8,"rest":"a 10 hojas de menta o hierbabuena"},{"raw":"20 ml de jarabe simple (ver sección 2)","qty":20,"rest":"ml de jarabe simple (ver sección 2)"},{"raw":"25 ml de jugo de limón","qty":25,"rest":"ml de jugo de limón"},{"raw":"Agua con gas al gusto","qty":null,"rest":"Agua con gas al gusto"},{"raw":"Hielo en cubos","qty":null,"rest":"Hielo en cubos"}]'::jsonb, '["Pon la menta y el jarabe en el fondo del vaso y machaca suave con una cuchara de palo (sin molerla, solo liberar el aroma).","Agrega el jugo de limón y el ron.","Llena el vaso con hielo.","Completa con agua con gas y revuelve una vez."]'::jsonb, '[]'::jsonb, '{"adelanta":"El jarabe simple se prepara con días de anticipación y se guarda en la nevera hasta 1 mes. El día del evento solo macheas la menta y armas.","presentacion":"Vaso alto, con una ramita de menta encima y pitillo.","conservacion":"Se toma de inmediato; si lo dejas listo pierde el gas en menos de 10 minutos.","variacion":"Es la base del mojito sin alcohol: mismo procedimiento, sin el ron.","variacion_titulo":"Sin alcohol"}'::jsonb) on conflict (store_id, slug) do update set category_id = excluded.category_id, title = excluded.title, position = excluded.position, photo_path = excluded.photo_path, photo_people_path = excluded.photo_people_path, yield_text = excluded.yield_text, yield_servings = excluded.yield_servings, time_text = excluded.time_text, ingredients = excluded.ingredients, steps = excluded.steps, notes = excluded.notes, extras = excluded.extras;
insert into public.recipes (store_id, category_id, slug, title, position, photo_path, photo_people_path, yield_text, yield_servings, time_text, ingredients, steps, notes, extras) values ((select id from public.stores where slug = 'cocteles'), (select id from public.recipe_categories where store_id = (select id from public.stores where slug = 'cocteles') and slug = 'clasicos-faciles'), 'gin-tonic', 'Gin tonic', 2, 'cocteles/foto-gin-tonic.jpg', 'cocteles/gente-gin-tonic.jpg', '1 vaso balón o alto (300 ml)', 1, '3 minutos', '[{"raw":"50 ml de ginebra","qty":50,"rest":"ml de ginebra"},{"raw":"150 ml de agua tónica bien fría","qty":150,"rest":"ml de agua tónica bien fría"},{"raw":"Cáscara de limón o de naranja","qty":null,"rest":"Cáscara de limón o de naranja"},{"raw":"Hielo en cubos grandes","qty":null,"rest":"Hielo en cubos grandes"}]'::jsonb, '["Llena el vaso con hielo.","Agrega la ginebra.","Completa con la tónica, dejándola caer despacio por el borde para no perder la burbuja.","Exprime la cáscara de cítrico sobre el vaso para soltar los aceites y déjala caer dentro."]'::jsonb, '[]'::jsonb, '{"adelanta":"Nada; entre más rápido lo sirvas después de abrir la tónica, mejor burbuja conserva. Si quieres, deja la ginebra y la tónica en la nevera desde el día anterior.","presentacion":"Vaso balón si tienes, o vaso alto. Cáscara de limón o naranja como garnish.","conservacion":"Se toma de inmediato.","variacion":"Tónica sola con mucho hielo y cítricos.","variacion_titulo":"Sin alcohol"}'::jsonb) on conflict (store_id, slug) do update set category_id = excluded.category_id, title = excluded.title, position = excluded.position, photo_path = excluded.photo_path, photo_people_path = excluded.photo_people_path, yield_text = excluded.yield_text, yield_servings = excluded.yield_servings, time_text = excluded.time_text, ingredients = excluded.ingredients, steps = excluded.steps, notes = excluded.notes, extras = excluded.extras;
insert into public.recipes (store_id, category_id, slug, title, position, photo_path, photo_people_path, yield_text, yield_servings, time_text, ingredients, steps, notes, extras) values ((select id from public.stores where slug = 'cocteles'), (select id from public.recipe_categories where store_id = (select id from public.stores where slug = 'cocteles') and slug = 'clasicos-faciles'), 'tequila-sunrise', 'Tequila sunrise', 3, 'cocteles/foto-tequila-sunrise.jpg', 'cocteles/gente-tequila-sunrise.jpg', '1 vaso alto (300 ml)', 1, '5 minutos', '[{"raw":"45 ml de tequila blanco","qty":45,"rest":"ml de tequila blanco"},{"raw":"120 ml de jugo de naranja natural","qty":120,"rest":"ml de jugo de naranja natural"},{"raw":"15 ml de granadina","qty":15,"rest":"ml de granadina"},{"raw":"Hielo en cubos","qty":null,"rest":"Hielo en cubos"}]'::jsonb, '["Llena el vaso con hielo.","Agrega el tequila y el jugo de naranja, revuelve.","Deja caer la granadina despacio por el borde del vaso sin revolver, para que quede al fondo y suba el degradé de color."]'::jsonb, '[]'::jsonb, '{"adelanta":"El jugo de naranja se puede exprimir el día anterior y guardar en la nevera. La granadina no necesita nada especial.","presentacion":"Vaso alto; se nota el degradé naranja-rojo si no revuelves al final. Rodaja de naranja en el borde.","conservacion":"Se toma de inmediato; si se deja reposar más de 15 minutos el degradé se mezcla solo.","variacion":"Jugo de naranja con granadina y soda.","variacion_titulo":"Sin alcohol"}'::jsonb) on conflict (store_id, slug) do update set category_id = excluded.category_id, title = excluded.title, position = excluded.position, photo_path = excluded.photo_path, photo_people_path = excluded.photo_people_path, yield_text = excluded.yield_text, yield_servings = excluded.yield_servings, time_text = excluded.time_text, ingredients = excluded.ingredients, steps = excluded.steps, notes = excluded.notes, extras = excluded.extras;
insert into public.recipes (store_id, category_id, slug, title, position, photo_path, photo_people_path, yield_text, yield_servings, time_text, ingredients, steps, notes, extras) values ((select id from public.stores where slug = 'cocteles'), (select id from public.recipe_categories where store_id = (select id from public.stores where slug = 'cocteles') and slug = 'clasicos-faciles'), 'margarita', 'Margarita', 4, null, null, '1 vaso bajo o copa margarita (250 ml)', 1, '5 minutos', '[{"raw":"45 ml de tequila blanco","qty":45,"rest":"ml de tequila blanco"},{"raw":"25 ml de triple sec (licor de naranja)","qty":25,"rest":"ml de triple sec (licor de naranja)"},{"raw":"25 ml de jugo de limón","qty":25,"rest":"ml de jugo de limón"},{"raw":"Sal para el borde (opcional)","qty":null,"rest":"Sal para el borde (opcional)"},{"raw":"Hielo en cubos","qty":null,"rest":"Hielo en cubos"}]'::jsonb, '["Humedece el borde del vaso con limón y pásalo por sal, si quieres la versión escarchada.","Pon el tequila, el triple sec, el jugo de limón y hielo en un frasco con tapa (la coctelera de casa).","Agita fuerte 15 segundos.","Sirve con hielo nuevo en el vaso o cuela si prefieres sin hielo."]'::jsonb, '[]'::jsonb, '{"adelanta":"Nada se adelanta; se agita al momento. El escarchado de sal en el borde se puede dejar listo desde antes.","presentacion":"Vaso bajo o copa tipo margarita, borde escarchado de sal y una rodaja de limón.","conservacion":"Se toma de inmediato.","variacion":"Jugo de limón y naranja con un chorrito de jarabe y soda.","variacion_titulo":"Sin alcohol"}'::jsonb) on conflict (store_id, slug) do update set category_id = excluded.category_id, title = excluded.title, position = excluded.position, photo_path = excluded.photo_path, photo_people_path = excluded.photo_people_path, yield_text = excluded.yield_text, yield_servings = excluded.yield_servings, time_text = excluded.time_text, ingredients = excluded.ingredients, steps = excluded.steps, notes = excluded.notes, extras = excluded.extras;
insert into public.recipes (store_id, category_id, slug, title, position, photo_path, photo_people_path, yield_text, yield_servings, time_text, ingredients, steps, notes, extras) values ((select id from public.stores where slug = 'cocteles'), (select id from public.recipe_categories where store_id = (select id from public.stores where slug = 'cocteles') and slug = 'clasicos-faciles'), 'pina-colada', 'Piña colada', 5, 'cocteles/foto-pina-colada.jpg', 'cocteles/gente-pina-colada.jpg', '1 vaso alto o copa huracán (350 ml)', 1, '8 minutos', '[{"raw":"45 ml de ron blanco","qty":45,"rest":"ml de ron blanco"},{"raw":"90 ml de jugo de piña","qty":90,"rest":"ml de jugo de piña"},{"raw":"45 ml de crema de coco","qty":45,"rest":"ml de crema de coco"},{"raw":"Hielo al gusto","qty":null,"rest":"Hielo al gusto"}]'::jsonb, '["Pon el ron, el jugo de piña, la crema de coco y un puñado de hielo en la licuadora.","Licua hasta que quede espumoso y sin grumos de hielo.","Sirve de inmediato en el vaso."]'::jsonb, '[]'::jsonb, '{"adelanta":"El jugo de piña se puede colar y guardar en la nevera hasta 2 días antes. El resto se licua al momento para que quede espumoso.","presentacion":"Vaso alto o copa huracán, un trozo de piña y una cereza en el borde.","conservacion":"Se toma recién licuada; el hielo se derrite rápido y la separa.","variacion":"Jugo de piña con crema de coco licuados con hielo, sin ron.","variacion_titulo":"Sin alcohol"}'::jsonb) on conflict (store_id, slug) do update set category_id = excluded.category_id, title = excluded.title, position = excluded.position, photo_path = excluded.photo_path, photo_people_path = excluded.photo_people_path, yield_text = excluded.yield_text, yield_servings = excluded.yield_servings, time_text = excluded.time_text, ingredients = excluded.ingredients, steps = excluded.steps, notes = excluded.notes, extras = excluded.extras;
insert into public.recipes (store_id, category_id, slug, title, position, photo_path, photo_people_path, yield_text, yield_servings, time_text, ingredients, steps, notes, extras) values ((select id from public.stores where slug = 'cocteles'), (select id from public.recipe_categories where store_id = (select id from public.stores where slug = 'cocteles') and slug = 'con-aguardiente-y-sabores-colombianos'), 'aguardiente-con-lulo-gualulado', 'Aguardiente con lulo (gualulado)', 6, null, null, '1 vaso alto (300 ml)', 1, '10 minutos (si el lulo ya está licuado)', '[{"raw":"45 ml de aguardiente","qty":45,"rest":"ml de aguardiente"},{"raw":"150 ml de jugo de lulo colado (sin semillas)","qty":150,"rest":"ml de jugo de lulo colado (sin semillas)"},{"raw":"10 ml de jarabe simple (ajustar al gusto, el lulo es ácido)","qty":10,"rest":"ml de jarabe simple (ajustar al gusto, el lulo es ácido)"},{"raw":"Hielo en cubos","qty":null,"rest":"Hielo en cubos"}]'::jsonb, '["Licua la pulpa de lulo con un poco de agua y cuela para sacar las semillas.","Llena el vaso con hielo.","Agrega el aguardiente, el jugo de lulo y el jarabe.","Revuelve bien porque el jugo de lulo es espeso y se asienta."]'::jsonb, '[]'::jsonb, '{"adelanta":"El jugo de lulo se licua y cuela hasta 2 días antes, se guarda en la nevera tapado. El día del evento solo se mezcla con el aguardiente.","presentacion":"Vaso alto, con una rodaja de lulo partida a la mitad en el borde.","conservacion":"El jugo de lulo solo, sin aguardiente, aguanta 2 días en la nevera bien tapado. Ya mezclado con el licor se toma el mismo día.","variacion":"Jugo de lulo con jarabe y agua con gas.","variacion_titulo":"Sin alcohol"}'::jsonb) on conflict (store_id, slug) do update set category_id = excluded.category_id, title = excluded.title, position = excluded.position, photo_path = excluded.photo_path, photo_people_path = excluded.photo_people_path, yield_text = excluded.yield_text, yield_servings = excluded.yield_servings, time_text = excluded.time_text, ingredients = excluded.ingredients, steps = excluded.steps, notes = excluded.notes, extras = excluded.extras;
insert into public.recipes (store_id, category_id, slug, title, position, photo_path, photo_people_path, yield_text, yield_servings, time_text, ingredients, steps, notes, extras) values ((select id from public.stores where slug = 'cocteles'), (select id from public.recipe_categories where store_id = (select id from public.stores where slug = 'cocteles') and slug = 'con-aguardiente-y-sabores-colombianos'), 'coctel-de-aguardiente-con-maracuya', 'Cóctel de aguardiente con maracuyá', 7, null, null, '1 vaso alto (300 ml)', 1, '10 minutos', '[{"raw":"45 ml de aguardiente","qty":45,"rest":"ml de aguardiente"},{"raw":"100 ml de jugo de maracuyá colado","qty":100,"rest":"ml de jugo de maracuyá colado"},{"raw":"15 ml de jarabe simple","qty":15,"rest":"ml de jarabe simple"},{"raw":"Hielo en cubos","qty":null,"rest":"Hielo en cubos"}]'::jsonb, '["Saca la pulpa de 2 maracuyás, licua con un poco de agua y cuela las semillas.","Llena el vaso con hielo.","Agrega el aguardiente, el jugo de maracuyá y el jarabe.","Revuelve bien hasta que quede parejo."]'::jsonb, '[]'::jsonb, '{"adelanta":"La pulpa de maracuyá se saca y se cuela hasta 2 días antes; se guarda en la nevera.","presentacion":"Vaso alto; puedes decorar el borde con un poco de azúcar humedecida con agua para que se pegue (escarchado).","conservacion":"La pulpa colada aguanta 2 días en nevera; ya armado se toma el mismo día.","variacion":"Jugo de maracuyá con jarabe y agua con gas.","variacion_titulo":"Sin alcohol"}'::jsonb) on conflict (store_id, slug) do update set category_id = excluded.category_id, title = excluded.title, position = excluded.position, photo_path = excluded.photo_path, photo_people_path = excluded.photo_people_path, yield_text = excluded.yield_text, yield_servings = excluded.yield_servings, time_text = excluded.time_text, ingredients = excluded.ingredients, steps = excluded.steps, notes = excluded.notes, extras = excluded.extras;
insert into public.recipes (store_id, category_id, slug, title, position, photo_path, photo_people_path, yield_text, yield_servings, time_text, ingredients, steps, notes, extras) values ((select id from public.stores where slug = 'cocteles'), (select id from public.recipe_categories where store_id = (select id from public.stores where slug = 'cocteles') and slug = 'con-aguardiente-y-sabores-colombianos'), 'limonada-de-mango-biche-con-aguardiente', 'Limonada de mango biche con aguardiente', 8, null, null, '1 vaso alto (300 ml)', 1, '15 minutos', '[{"raw":"45 ml de aguardiente","qty":45,"rest":"ml de aguardiente"},{"raw":"1 mango biche (verde) mediano","qty":1,"rest":"mango biche (verde) mediano"},{"raw":"30 ml de jugo de limón","qty":30,"rest":"ml de jugo de limón"},{"raw":"15 ml de jarabe simple o panela disuelta","qty":15,"rest":"ml de jarabe simple o panela disuelta"},{"raw":"Una pizca de sal","qty":null,"rest":"Una pizca de sal"},{"raw":"Hielo en cubos","qty":null,"rest":"Hielo en cubos"}]'::jsonb, '["Pela el mango biche y lícualo con 200 ml de agua, el jugo de limón y el jarabe.","Cuela si quieres una textura más ligera.","Llena el vaso con hielo, agrega el aguardiente y completa con la limonada de mango biche.","Revuelve y ajusta de sal: una pizca resalta el dulce-ácido del mango."]'::jsonb, '[]'::jsonb, '{"adelanta":"La limonada de mango biche (sin aguardiente) se prepara el día anterior y se guarda en la nevera hasta 2 días. El aguardiente se agrega al servir, nunca antes, para que no pierda gas si lleva soda.","presentacion":"Vaso alto; escarchado con sal y azúcar mezcladas en el borde.","conservacion":"La limonada sola aguanta 2 días en nevera; con aguardiente se toma el mismo día.","variacion":"Es la limonada de mango biche, tal cual, sin el aguardiente.","variacion_titulo":"Sin alcohol"}'::jsonb) on conflict (store_id, slug) do update set category_id = excluded.category_id, title = excluded.title, position = excluded.position, photo_path = excluded.photo_path, photo_people_path = excluded.photo_people_path, yield_text = excluded.yield_text, yield_servings = excluded.yield_servings, time_text = excluded.time_text, ingredients = excluded.ingredients, steps = excluded.steps, notes = excluded.notes, extras = excluded.extras;
insert into public.recipes (store_id, category_id, slug, title, position, photo_path, photo_people_path, yield_text, yield_servings, time_text, ingredients, steps, notes, extras) values ((select id from public.stores where slug = 'cocteles'), (select id from public.recipe_categories where store_id = (select id from public.stores where slug = 'cocteles') and slug = 'con-aguardiente-y-sabores-colombianos'), 'aguardiente-con-guanabana', 'Aguardiente con guanábana', 9, null, null, '1 vaso alto (300 ml)', 1, '10 minutos', '[{"raw":"45 ml de aguardiente","qty":45,"rest":"ml de aguardiente"},{"raw":"100 g de pulpa de guanábana (sin semillas)","qty":100,"rest":"g de pulpa de guanábana (sin semillas)"},{"raw":"100 ml de agua o leche fría (opcional, para versión más cremosa)","qty":100,"rest":"ml de agua o leche fría (opcional, para versión más cremosa)"},{"raw":"15 ml de jarabe simple","qty":15,"rest":"ml de jarabe simple"},{"raw":"Hielo en cubos","qty":null,"rest":"Hielo en cubos"}]'::jsonb, '["Licua la pulpa de guanábana con el agua o la leche y el jarabe hasta que quede suave.","Cuela si quedan hilachas de la fruta.","Llena el vaso con hielo, agrega el aguardiente y completa con la mezcla de guanábana.","Revuelve bien porque la guanábana es espesa."]'::jsonb, '[]'::jsonb, '{"adelanta":"La pulpa de guanábana se licua y cuela hasta 2 días antes; se guarda en la nevera porque oxida rápido.","presentacion":"Vaso alto; se ve cremoso y claro. Puedes rallar un poco de canela encima.","conservacion":"La mezcla de guanábana sola se oxida rápido: mejor preparar el mismo día o un día antes como máximo, bien tapada.","variacion":"Batido de guanábana con leche y jarabe.","variacion_titulo":"Sin alcohol"}'::jsonb) on conflict (store_id, slug) do update set category_id = excluded.category_id, title = excluded.title, position = excluded.position, photo_path = excluded.photo_path, photo_people_path = excluded.photo_people_path, yield_text = excluded.yield_text, yield_servings = excluded.yield_servings, time_text = excluded.time_text, ingredients = excluded.ingredients, steps = excluded.steps, notes = excluded.notes, extras = excluded.extras;
insert into public.recipes (store_id, category_id, slug, title, position, photo_path, photo_people_path, yield_text, yield_servings, time_text, ingredients, steps, notes, extras) values ((select id from public.stores where slug = 'cocteles'), (select id from public.recipe_categories where store_id = (select id from public.stores where slug = 'cocteles') and slug = 'con-aguardiente-y-sabores-colombianos'), 'aguardiente-con-corozo', 'Aguardiente con corozo', 10, null, null, '1 vaso alto (300 ml)', 1, '15 minutos', '[{"raw":"45 ml de aguardiente","qty":45,"rest":"ml de aguardiente"},{"raw":"150 ml de jugo de corozo colado y endulzado","qty":150,"rest":"ml de jugo de corozo colado y endulzado"},{"raw":"Hielo en cubos","qty":null,"rest":"Hielo en cubos"}]'::jsonb, '["Hierve la pulpa de corozo en agua durante 10 minutos, machaca y cuela para sacar el jugo.","Endulza el jugo a tu gusto mientras aún está tibio.","Deja enfriar, llena el vaso con hielo, agrega el aguardiente y completa con el jugo de corozo."]'::jsonb, '[]'::jsonb, '{"adelanta":"El jugo de corozo (fruta de la costa caribe) se prepara con días de anticipación: se hierve la pulpa, se cuela y se guarda en la nevera hasta 3 días.","presentacion":"Vaso alto; el jugo de corozo tiene un color morado intenso que se ve muy bien solo.","conservacion":"El jugo de corozo solo aguanta 3 días en nevera bien tapado; con aguardiente se toma el mismo día.","variacion":"Es el jugo de corozo, servido solo con hielo.","variacion_titulo":"Sin alcohol"}'::jsonb) on conflict (store_id, slug) do update set category_id = excluded.category_id, title = excluded.title, position = excluded.position, photo_path = excluded.photo_path, photo_people_path = excluded.photo_people_path, yield_text = excluded.yield_text, yield_servings = excluded.yield_servings, time_text = excluded.time_text, ingredients = excluded.ingredients, steps = excluded.steps, notes = excluded.notes, extras = excluded.extras;
