insert into public.recipes (store_id, category_id, slug, title, position, photo_path, photo_people_path, yield_text, yield_servings, time_text, ingredients, steps, notes, extras) values ((select id from public.stores where slug = 'cocteles'), (select id from public.recipe_categories where store_id = (select id from public.stores where slug = 'cocteles') and slug = 'nuevos-y-llamativos'), 'paloma', 'Paloma', 23, 'cocteles/foto-paloma.jpg', 'cocteles/gente-paloma.jpg', '1 vaso alto (300 ml)', 1, '4 minutos', '[{"raw":"45 ml de tequila blanco","qty":45,"rest":"ml de tequila blanco"},{"raw":"120 ml de soda sabor toronja (grapefruit) bien fría","qty":120,"rest":"ml de soda sabor toronja (grapefruit) bien fría"},{"raw":"10 ml de jugo de limón","qty":10,"rest":"ml de jugo de limón"},{"raw":"Sal para el borde (opcional)","qty":null,"rest":"Sal para el borde (opcional)"},{"raw":"Hielo en cubos","qty":null,"rest":"Hielo en cubos"}]'::jsonb, '["Humedece el borde del vaso con limón y pásalo por sal, si quieres la versión escarchada.","Llena el vaso con hielo.","Agrega el tequila y el jugo de limón.","Completa con la soda de toronja despacio."]'::jsonb, '[]'::jsonb, '{"adelanta":"Nada; se arma al momento para que no pierda el gas de la soda.","presentacion":"Vaso alto, rodaja de toronja o limón en el borde.","conservacion":"Se toma de inmediato."}'::jsonb) on conflict (store_id, slug) do update set category_id = excluded.category_id, title = excluded.title, position = excluded.position, photo_path = excluded.photo_path, photo_people_path = excluded.photo_people_path, yield_text = excluded.yield_text, yield_servings = excluded.yield_servings, time_text = excluded.time_text, ingredients = excluded.ingredients, steps = excluded.steps, notes = excluded.notes, extras = excluded.extras;
insert into public.recipes (store_id, category_id, slug, title, position, photo_path, photo_people_path, yield_text, yield_servings, time_text, ingredients, steps, notes, extras) values ((select id from public.stores where slug = 'cocteles'), (select id from public.recipe_categories where store_id = (select id from public.stores where slug = 'cocteles') and slug = 'nuevos-y-llamativos'), 'spritz-de-naranja-estilo-aperitivo-con-vino-espumoso', 'Spritz de naranja (estilo aperitivo con vino espumoso)', 24, null, null, '1 copa de vino (250 ml)', 1, '4 minutos', '[{"raw":"90 ml de vino espumoso frío","qty":90,"rest":"ml de vino espumoso frío"},{"raw":"60 ml de jugo de naranja natural","qty":60,"rest":"ml de jugo de naranja natural"},{"raw":"30 ml de soda","qty":30,"rest":"ml de soda"},{"raw":"Hielo en cubos","qty":null,"rest":"Hielo en cubos"},{"raw":"Rodaja de naranja","qty":null,"rest":"Rodaja de naranja"}]'::jsonb, '["Llena la copa con hielo.","Agrega el jugo de naranja.","Completa con el vino espumoso.","Termina con un chorrito de soda y revuelve suave.","Decora con la rodaja de naranja."]'::jsonb, '[]'::jsonb, '{"adelanta":"Nada; se arma al momento para que no pierda la burbuja del espumoso.","presentacion":"Copa de vino grande, rodaja de naranja en el borde.","conservacion":"Se toma de inmediato.","variacion":"Versión casera del spritz clásico: cambia el licor amargo importado por vino espumoso y naranja, fácil de conseguir en Colombia.","variacion_titulo":"Sin alcohol"}'::jsonb) on conflict (store_id, slug) do update set category_id = excluded.category_id, title = excluded.title, position = excluded.position, photo_path = excluded.photo_path, photo_people_path = excluded.photo_people_path, yield_text = excluded.yield_text, yield_servings = excluded.yield_servings, time_text = excluded.time_text, ingredients = excluded.ingredients, steps = excluded.steps, notes = excluded.notes, extras = excluded.extras;
